	/**
	 * Post repository change events to the client.
	 * @param events change events
	 */
	public void dispatchEvents(RepositoryChangeEvent[] events) {
		lock (eventQueue) {
			if (!isValid) {
				return;
			}
			foreach (RepositoryChangeEvent @event in events) {
				eventQueue.addLast(@event);
			}
			eventQueue.notifyAll();
		}
	}

	/**
	 * Verify that the client is active and continuing to read events
	 */
	public void checkHandle() {
		if (!isValid) {
			return;
		}

		RepositoryChangeEvent openFileCountEvent =
			new RepositoryChangeEvent(RepositoryChangeEvent.REP_OPEN_HANDLE_COUNT, null, null, null,
				Integer.toString(RemoteBufferFileImpl.getOpenFileCount(this)));

		lock (eventQueue) {
			if (clientActive) {
				clientActive = false;
				if (eventQueue.isEmpty()) {

					//eventQueue.add(0, NULL_EVENT);

					// Send open-file count periodically instead of null event
					eventQueue.add(openFileCountEvent);

					eventQueue.notifyAll();
				}
				return;
			}
		}
		repository.log(null, "Not listening (may be sleeping)!", currentUser);
		dispose();
	}

	/* @Override */
	public RepositoryChangeEvent[] getEvents()
    {
		lock (eventQueue) {
			clientActive = true;
