	private void checkFileInUse(string parentPath, string itemName)
    {
		string[] openFileUsers = RemoteBufferFileImpl.getOpenFileUsers(repository.getName(),
			getPathname(parentPath, itemName));
		if (openFileUsers != null) {
			StringBuffer buf = new StringBuffer("");
			foreach (string user in openFileUsers) {
				if (buf.length() != 0) {
					buf.append(", ");
				}
				buf.append(user);
			}
			throw new FileInUseException(itemName + " in use by: " + buf.toString());
		}
	}

	private void checkFolderInUse(string parentPath, string folderName)
    {
		RepositoryFolder folder;
		try {
			folder = repository.getFolder(currentUser, getPathname(parentPath, folderName), false);
			if (folder == null) {
				return;
			}
			if (isFolderInUse(folder)) {
				throw new FileInUseException("Repository folder " + folderName +
					" contains one or more files that are checked-out by one or more users.");
			}
		}
		catch (InvalidNameException e) {
			// ignore
		}
	}

	private bool isFolderInUse(RepositoryFolder folder)
    {
		foreach (RepositoryFolder f in folder.getFolders()) {
			if (isFolderInUse(f)) {
				return true;
			}
		}
		foreach (RepositoryFile rf in folder.getFiles()) {
			if (rf.hasCheckouts()) {
				return true;
			}
			string[] openFileUsers = RemoteBufferFileImpl.getOpenFileUsers(repository.getName(),
				getPathname(folder.getPathname(), rf.getName()));
			if (openFileUsers != null) {
				return true;
			}
		}
		return false;
	}

	/* @Override */
	public ItemCheckoutStatus checkout(string parentPath, string itemName,
			CheckoutType checkoutType, string projectPath)
    {
		lock (syncObject) {
			validate();
			try {
				repository.validateWritePrivilege(currentUser);
				RepositoryFile rf = getFile(parentPath, itemName);
				if (rf == null) {
					throw new FileNotFoundException(itemName + " not found in repository");
				}
				ItemCheckoutStatus checkoutStatus =
					rf.checkout(checkoutType, currentUser, projectPath);
				if (checkoutStatus != null &&
					checkoutStatus.getCheckoutType() == CheckoutType.TRANSIENT) {
					addTransientCheckout(rf.getPathname(), checkoutStatus);
				}
				return checkoutStatus;
			}
			catch (Throwable t) {
				throw RemoteExceptionUtil.dispatchIOException(t, repoName,
					getPathname(parentPath, itemName),
					"Checkout item (" + checkoutType + ") to " + projectPath, currentUser);
			}
		}
	}

