					"Check item", currentUser);
			}
		}
	}

	/* @Override */
	public long getLength(string parentPath, string itemName)
    {
		lock (syncObject) {
			validate();
			RepositoryFile rf;
			try {
				rf = getFile(parentPath, itemName);
				if (rf == null) {
					return 0;
				}
				return rf.length();
			}
			catch (FileNotFoundException e) {
				return 0;
			}
			catch (Throwable t) {
				throw RemoteExceptionUtil.dispatchIOException(t, repoName,
					getPathname(parentPath, itemName),
					"Get item length", currentUser);
			}
		}
	}

	/* @Override */
	public bool hasCheckouts(string parentPath, string itemName)
    {
		lock (syncObject) {
			validate();
			try {
				RepositoryFile rf = getFile(parentPath, itemName);
				if (rf == null) {
					throw new FileNotFoundException(itemName + " not found in repository");
				}
				return rf.hasCheckouts();
			}
			catch (Throwable t) {
				throw RemoteExceptionUtil.dispatchIOException(t, repoName,
					getPathname(parentPath, itemName),
					"Has checkouts", currentUser);
			}
		}
	}

	/* @Override */
	public bool isCheckinActive(string parentPath, string itemName)
    {
		lock (syncObject) {
			validate();
			try {
				RepositoryFile rf = getFile(parentPath, itemName);
				if (rf == null) {
					throw new FileNotFoundException(itemName + " not found in repository");
				}
				return rf.isCheckinActive();
			}
			catch (Throwable t) {
				throw RemoteExceptionUtil.dispatchIOException(t, repoName,
					getPathname(parentPath, itemName),
					"Is checkin active", currentUser);
			}
		}
	}

	private static string getPathname(string parentPath, string itemName) {
		StringBuffer path = new StringBuffer(parentPath);
		if (path.charAt(path.length() - 1) != FileSystem.SEPARATOR_CHAR) {
			path.append(FileSystem.SEPARATOR_CHAR);
		}
		path.append(itemName);
		return path.toString();
	}

}
